import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
public class LinguisticPuzzleSolver {

    private static Map<String, String> words = new HashMap<String, String>();

    static {
        words.put("macin", "canvas");
        words.put("loipcat", "clip");
        words.put("robed", "bored");
        words.put("death", "thread");
        words.put("detrsses", "stressed");
    }

    public static String solve(String puzzle) {
        char[] letters = puzzle.toCharArray();
        Arrays.sort(letters);
        String sorted = new String(letters);

        for (Map.Entry<String, String> entry : words.entrySet()) {
            char[] wordLetters = entry.getKey().toCharArray();
            Arrays.sort(wordLetters);
            String sortedWord = new String(wordLetters);

            if (sorted.equals(sortedWord)) {
                return entry.getValue();
            }
        }

        return null;
    }

    public static void main(String[] args) {
        String puzzle1 = "macin";
        String puzzle2 = "loipcat";
        String puzzle3 = "robed";
        String puzzle4 = "death";
        String puzzle5 = "detrsses";

