        System.out.println(puzzle2 + " -> " + solve(puzzle2));
        System.out.println(puzzle3 + " -> " + solve(puzzle3));
        System.out.println(puzzle4 + " -> " + solve(puzzle4));
        System.out.println(puzzle5 + " -> " + solve(puzzle5));
    }
}
