import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        // Generate a list of 10 random numbers between 1 and 100
        int[] numbers = new int[10];
        for (int i = 0; i < numbers.length; i++) {
            numbers[i] = (int) (Math.random() * 100) + 1;
        }
        // Sort the list in ascending order
        Arrays.sort(numbers);
        // Set the target value (unknown)
        int target = (int) (Math.random() * 200) + 1;
        // Start the timer
        long startTime = System.nanoTime();
        // Iterate through the list and find the two numbers that add up to the target value
        for (int i = 0; i < numbers.length; i++) {
            for (int j = i+1; j < numbers.length; j++) {
                if (numbers[i] + numbers[j] == target) {
                    // Stop the timer
                    long endTime = System.nanoTime();
                    // Print the pair of numbers and execution time
                    System.out.printf("Pair found: (%d, %d). Execution time: %.6f seconds", numbers[i], numbers[j], (endTime - startTime) / 1e9);
