<?php
function generateRandomString($sum) {
    $string = '';
    while (true) {
        for ($i = 0; $i < 10; $i++) {
            $random = mt_rand(1, $sum);
            $sum -= $random;
            $string .= chr($random + 96);
        }
        if ($sum == 0) {
            break;
        } else {
            $sum = $sum + array_sum(array_map('ord', str_split($string))) - 960;
            $string = '';
        }
    }
    return $string;
}
// Example usage
