            cerr << "HTTP request failed: " << curl_easy_strerror(res) << endl;
            return 1;
        }
        // Parse the HTML content using RapidXML
        xml_document<> doc;
        doc.parse<0>(&html_content[0]);
        // Find the interesting facts section
        xml_node<> *facts_section = doc.first_node("html")->first_node("body")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("div")->first_node("ul");
        // Print the top 3 interesting facts
        int count = 0;
        for (xml_node<> *fact = facts_section->first_node("li"); fact && count < 3; fact = fact->next_sibling("li"))
        {
            cout << fact->value() << endl;
            count++;
        }
    }
    // Cleanup
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return 0;
}
```
This code uses libcurl to make an HTTP request to the website and retrieve the HTML content. It then uses RapidXML to parse the HTML content and find the interesting facts section. Finally, it prints out the top 3 interesting facts.
Note that you will need to install libcurl and RapidXML libraries and link them to your C++ project in order to compile and run this code.

