Here is the C# code to calculate the cosine similarity between the vector representation of the given text and each of the three topic categories using the provided XML data format:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;
namespace CosineSimilarityCalculator
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the XML data
            XDocument xml = XDocument.Parse(@"
                <topics>
                    <topic>
                        <category>Topic 1</category>
                        <vector>[0.8, 0.5, 0.3, 0.1]</vector>
                    </topic>
                    <topic>
                        <category>Topic 2</category>
                        <vector>[0.7, 0.3, 0.6, 0.2]</vector>
                    </topic>
                    <topic>
                        <category>Topic 3</category>
                        <vector>[0.2, 0.6, 0.4, 0.8]</vector>
                    </topic>
                </topics>");
            // Parse the XML data into a dictionary of category-vector pairs
            Dictionary<string, double[]> categoryVectors = xml.Descendants("topic")
                .ToDictionary(
                    t => t.Element("category").Value,
                    t => t.Element("vector").Value
                        .Trim('[', ']')
                        .Split(',')
                        .Select(s => double.Parse(s.Trim()))
                        .ToArray());
            // Get the vector representation of the given text
            double[] textVector = new double[] { 0.5, 0.2, 0.4, 0.7 };
            // Calculate the cosine similarity between the text vector and each category vector
            Dictionary<string, double> cosineSimilarities = categoryVectors.ToDictionary(
                kvp => kvp.Key,
                kvp => DotProduct(textVector, kvp.Value) / (Magnitude(textVector) * Magnitude(kvp.Value)));
            // Print the cosine similarities in descending order
            foreach (var kvp in cosineSimilarities.OrderByDescending(kvp => kvp.Value))
            {
                Console.WriteLine($"{kvp.Key}: {kvp.Value}");
            }
        }
        static double DotProduct(double[] a, double[] b)
        {
            return a.Zip(b, (x, y) => x * y).Sum();
        }
        static double Magnitude(double[] a)
        {
            return Math.Sqrt(DotProduct(a, a));
        }
    }
}
```
In this code, we first load the XML data and parse it into a dictionary of category-vector pairs. We then get the vector representation of the given text and calculate the cosine similarity between the text vector and each category vector using the provided formula. Finally, we print the cosine similarities in descending order. The `DotProduct` and `Magnitude` methods are helper methods to calculate the dot product and Euclidean norm of vectors, respectively.

