How can I use C# to generate a set of 150 words for a crossword puzzle? Can you provide a sample C# code that will randomly select 150 words from a table called 'crossword_words' in a SQL database and output them as a grid for the puzzle?
Here is a sample C# code that uses the SQL query to select 150 random words from the 'crossword_words' table and output them as a grid for the crossword puzzle:
```csharp
using System;
using System.Data.SqlClient;
namespace CrosswordPuzzleGenerator
{
    class Program
    {
        static void Main(string[] args)
        {
            string connectionString = "Data Source=YourServerName;Initial Catalog=YourDatabaseName;Integrated Security=True";
            SqlConnection connection = new SqlConnection(connectionString);
            connection.Open();
            SqlCommand command = new SqlCommand("SELECT TOP 150 * FROM crossword_words ORDER BY NEWID()", connection);
            SqlDataReader reader = command.ExecuteReader();
            string[] words = new string[150];
            int index = 0;
            while (reader.Read())
            {
                words[index] = reader.GetString(0);
                index++;
            }
            reader.Close();
            connection.Close();
            // Create grid for crossword puzzle
            char[,] grid = new char[15, 15];
            for (int i = 0; i < 15; i++)
            {
                for (int j = 0; j < 15; j++)
                {
                    grid[i, j] = '_';
                }
            }
            // Insert words horizontally
            foreach (string word in words)
            {
                int row = new Random().Next(0, 15);
                int col = new Random().Next(0, 16 - word.Length);
                for (int i = 0; i < word.Length; i++)
                {
                    grid[row, col + i] = word[i];
                }
            }
            // Insert words vertically
            foreach (string word in words)
            {
                int row = new Random().Next(0, 16 - word.Length);
                int col = new Random().Next(0, 15);
                for (int i = 0; i < word.Length; i++)
                {
                    grid[row + i, col] = word[i];
                }
            }
            // Print grid for crossword puzzle
            for (int i = 0; i < 15; i++)
            {
                for (int j = 0; j < 15; j++)
                {
                    Console.Write(grid[i, j] + " ");
                }
                Console.WriteLine();
            }
        }
    }
}
```
To use this code, simply replace 'crossword_words' with the name of your table in the SQL query and run the C# code. This code will generate a crossword puzzle grid with 150 random words from the table.

